<?= $csrf->field() ?><label>Title<input name="title" maxlength="220" required value="<?= $e($event['title']??'') ?>"></label><label>Type<select name="event_type" required><?php foreach($types as$type):?><option value="<?= $e($type['public_id']) ?>" <?= ($event['type_public_id']??'')===$type['public_id']?'selected':'' ?>><?= $e($type['name']) ?></option><?php endforeach;?></select></label><label>Date<input type="date" name="event_date" required value="<?= $e($event['event_date']??'') ?>"></label><label>Start time<input type="time" name="start_time" value="<?= $e(isset($event['start_time'])?substr((string)$event['start_time'],0,5):'') ?>"></label><label>End time<input type="time" name="end_time" value="<?= $e(isset($event['end_time'])?substr((string)$event['end_time'],0,5):'') ?>"></label><label>Registration deadline<input type="datetime-local" name="registration_deadline" value="<?= $e(isset($event['registration_deadline'])?str_replace(' ','T',substr((string)$event['registration_deadline'],0,16)):'') ?>"></label><label>Venue<input name="venue" maxlength="300" value="<?= $e($event['venue']??'') ?>"></label><label>Online HTTPS URL<input type="url" name="online_url" maxlength="2048" value="<?= $e($event['online_url']??'') ?>"></label><label>Capacity<input type="number" min="1" name="capacity" value="<?= $e($event['capacity']??'') ?>"></label><label>Fee<input type="number" min="0" step="0.01" name="fee" value="<?= $e($event['fee']??'') ?>"></label><label>Currency<input name="fee_currency" maxlength="3" value="<?= $e($event['fee_currency']??'') ?>"></label><label>Registration access<select name="registration_access"><option value="public" <?= ($event['registration_access']??'public')==='public'?'selected':'' ?>>Public</option><option value="member" <?= ($event['registration_access']??'')==='member'?'selected':'' ?>>Members only</option></select></label><label>Status<select name="status"><?php foreach(['draft','published','cancelled','completed']as$status):?><option value="<?= $status ?>" <?= ($event['status']??'draft')===$status?'selected':'' ?>><?= ucfirst($status) ?></option><?php endforeach;?></select></label><label>Validated banner path<input name="banner_path" maxlength="500" placeholder="/assets/uploads/events/banner.webp" value="<?= $e($event['banner_path']??'') ?>"></label><label class="field-wide">Description<textarea name="description" maxlength="20000"><?= $e($event['description']??'') ?></textarea></label><label class="field-wide">Eligibility<textarea name="eligibility" maxlength="10000"><?= $e($event['eligibility']??'') ?></textarea></label><button class="btn btn-navy" type="submit"><?= $e($submit) ?></button>
